        int quantity = 3;
        double price = 149.5;
        final double GST = 0.18;
        double subtotal = quantity * price;
        double total = subtotal + subtotal * GST;
        System.out.printf("Subtotal: %.2f%n", subtotal);
        System.out.printf("Total with GST: %.2f%n", total);
    }
}

import java.util.Scanner;

